  "style": {
    "description": "A modern 'Athletic-Industrial' aesthetic. Typography: Archivo (Sans, 400-900) for high-impact headings and readability; DM Mono (400-500) for technical 'eyebrows', status chips, and data points. Colors: Deep Navy (#0f172a), Rail Slate (#090d16), and Border Blue (#1e293b) form the core. Accent: Ready Green (#16a34a) for success/primary actions. Animations use cubic-bezier(0.2, 0.6, 0.3, 1) for a snappy, fluid feel. Borders are thin (1px) with radii ranging from 6px (small) to 999px (pill).",
    "prompt": "Create a design system using a dark-mode palette: primary bg #0f172a, secondary surface #090d16, borders #1e293b. Accent color is #16a34a (Ready Green). Typography: Archivo for all body and headers, DM Mono for all metadata, labels, and small technical tags. Headers should be font-weight: 900 with tight letter-spacing. UI elements must have 10px corner radius unless pill-shaped. Buttons: primary is white with #0f172a text, secondary is outlined with 2px #1e293b. Include status colors: #d97706 (waiting), #dc2626 (blocked), and #0284c7 (info), each with a corresponding 'soft' background (10-20% opacity) for status chips."
  },
  "layout_and_structure": {
    "description": "A modular layout utilizing sticky sidebars, hero grids, and bento-style cards. The structure emphasizes the 'switching lens' concept where a single entity is viewed through different functional roles.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Fixed top bar, height 80px (shrinks to 64px on scroll). Background: #090d16 with 95% opacity and backdrop-blur(12px). Border-bottom: 1px solid #1e293b. Right side: login link and a pill-shaped 'Register' CTA."
      },
      {
        "part": "Hero Section",
        "prompt": "Split 2-column layout. Background features subtle SVG pitch lines (center circle, goal boxes) in #1e293b that self-draw on load using stroke-dashoffset. Left column: Massive 900-weight typography with staggered reveal animations. Right column: A 'Role Lens' graphic—a central card (#0f172a) surrounded by an orbiting ring of rotating role labels (Player, Coach, etc.). Labels must counter-rotate to stay horizontal while the ring spins."
      },
      {
        "part": "How It Works Timeline",
        "prompt": "A progress-bar style horizontal timeline. Features a track in #e2e8f0 and a fill/token in #16a34a. The token (24px circle with 4px white border) should move its horizontal 'left' percentage based on the user's scroll position within the section. Below the track, use a 5-column grid with circular icons and status chips."
      },
      {
        "part": "Role Switcher Workspace",
        "prompt": "A two-column sticky layout. Left side: A vertical list of 'Role' cards. Active card has a 4px #16a34a left-border. Right side: A sticky mobile-device mockup (#090d16 frame). Inside the device, content cross-fades (opacity 0 to 1) between different data views based on which role is active or scrolled into view on the left."
      },
      {
        "part": "Matchday Pitch Visualization",
        "prompt": "A dark green or navy rectangle with white schematic lines representing a field. 4-3-3 formation represented by colored dots (28px circles). GK, DF, MF, FW labels in font-size 10px Archivo Bold. Include a 'Referee' dot in a contrasting yellow (#d97706). Items should 'pop' in with a scale(0.4 to 1) animation when section becomes visible."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Status Chip",
      "description": "A pill-shaped indicator used for state and tagging.",
      "prompt": "Height: 24px. Padding: 4px 10px. Border-radius: 999px. Background: Variable (e.g., #dcfce7 for success). Text: DM Mono, 11px, uppercase, letter-spacing: 0.06em. Includes a 7px circular dot (solid color) to the left of the text."
    },
    {
      "component": "Interactive Lens Ring",
      "description": "A complex orbital navigation or visual element.",
      "prompt": "Container: 420px square. Animation: 'spin' 20s linear infinite. Children: 'chips' positioned absolutely at 0, 90, 180, 270 degrees. Nested span inside chips: Animation: 'counterspin' 20s linear infinite (reverse of parent) to keep text legible."
    }
  ],
  "special_notes": "MUST use DM Mono for all text inside pill-shaped status chips. MUST ensure all primary buttons have a minimum height of 44px for accessibility. MUST use a 'reveal' class for scroll animations that translates 24px upwards while fading in. DO NOT use rounded corners larger than 16px for cards—keep them sharp and professional. DO NOT use pure black; always use #0f172a for the deepest backgrounds."
}

{
  "summary": "PitchPeople is a modern sports-tech design system focused on 'One identity, every role'. It combines deep navy surfaces with vibrant green accents, utilizing a status-chip system (Ready, Waiting, Blocked, Info) to manage complex data states. The layout shifts from a dark, animated hero section to a clean, light-mode functional workspace, using mono-spaced typography for eyebrows and status labels to convey technical precision.",
  "style": {
    "description": "The style uses a 'Pitch' aesthetic—reminiscent of a football field under lights. It features high-contrast dark navy (#0f172a) backgrounds paired with vibrant green (#16a34a) and lime (#84cc16) accents. Typography pairs the bold, industrial 'Archivo' for headings with 'DM Mono' for technical metadata. Components use subtle borders (#e2e8f0), large rounded corners (10px-16px), and smooth cubic-bezier transitions (0.2, 0.6, 0.3, 1) for reveals.",
    "prompt": "Create a design system with the following specs: Colors: Pitch (#0f172a), Rail (#090d16), Ready (#16a34a), Waiting (#d97706), Blocked (#dc2626), Volt (#84cc16), Ink (#0f172a), and Surface (#ffffff). Typography: Use 'Archivo' for headings (weights 700-900, tracking-tight) and body; use 'DM Mono' for eyebrows (11px, uppercase, 0.08em letter-spacing) and status labels. UI Elements: Rounded corners at 10px (default) and 999px (pills). Status Chips: Background colors should be 'soft' versions of the main status color (e.g., ReadySoft #dcfce7) with a small 7px circular dot and 11px mono text. Animation: Use cubic-bezier(0.2, 0.6, 0.3, 1) for all entrance transforms. Buttons: Primary buttons are white pills with Ink text; secondary buttons are transparent with 2px borders."
  },
  "layout_and_structure": {
    "description": "The layout is a single-page flow starting with a high-impact dark hero, moving into a multi-state timeline, followed by a sticky-split feature section, and concluding with a tactical grid visualization.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Fixed header with a height of 80px (shrinking to 64px on scroll). Background: Rail (#090d16) at 95% opacity with backdrop-blur. Layout: Left-aligned logo (SVG square with rounded corners and center circle), center-aligned links (DM Mono, small), and right-aligned CTA buttons (one ghost 'Sign in', one white pill 'Start')."
      },
      {
        "part": "Hero Section",
        "prompt": "Background: Rail (#090d16). Layout: 2-column grid. Left side: Eye-brow text, massive stacked headers in Archivo (text-5xl to 6xl, leading 1.08), and two pill buttons. Right side: A 'Person Lens' card—a central card with an avatar and status chip, surrounded by a 420px rotating ring of floating status chips (Player, Coach, Referee). Background layer: SVG pitch markings that self-draw on page load using stroke-dashoffset animation."
      },
      {
        "part": "Functional Timeline",
        "prompt": "A 5-step horizontal process flow. Background: Surface (#ffffff). Elements: A 4px thick horizontal track (#e2e8f0) that fills with Ready Green (#16a34a) as the user scrolls. A sliding circular token (24px) moves along the track. Below the track, 5 columns each feature a circular icon (48px, bg-bgsunk), a bold title, and a status chip."
      },
      {
        "part": "Sticky Split Roles",
        "prompt": "Background: Bgsunk (#f1f5f9). Layout: Left side contains a scrollable list of 5 role items (each with a 4px left border that turns green when active). Right side: A sticky phone-shaped container (300px width, bg-rail) with a rounded inner screen that cross-fades between different UI mockups (Registrar, Coach, Guardian, etc.) as the user scrolls through or clicks the roles on the left."
      },
      {
        "part": "Tactical Matchday Grid",
        "prompt": "Layout: 3-column grid. Left (2 columns): A tactical football pitch visualization (bg-pitch) showing a 4-3-3 formation of circular 'shirt' dots (bg-ready) that pop in on scroll. Right (1 column): A calendar/fixture list with entries that slide up sequentially, each containing a date, matchup, and status chip (e.g., 'Ref due' in amber)."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "The Status Chip",
      "description": "A versatile pill-shaped badge used for indicating system states.",
      "prompt": "Implementation: Height 24px, padding 4px 10px. Border-radius 999px. Structure: One 7px diameter solid circle (dot) followed by text in DM Mono, 11px, uppercase. Color variations: Ready (Green dot, #dcfce7 bg, #14532d text), Waiting (Amber dot, #fef3c7 bg, #78350f text), Blocked (Red dot, #fee2e2 bg, #7f1d1d text), Info (Blue dot, #e0f2fe bg, #1e293b text)."
    },
    {
      "component": "Rotating Role Ring",
      "description": "An animated orbital menu used for displaying multiple identities.",
      "prompt": "Implementation: A parent container with a 420px diameter. A central static profile card. An outer ring that rotates at 20s per cycle. Floating on this ring are 'chips' (status chips). Critical detail: The chips must counter-rotate so the text remains horizontal while the entire orbital system spins."
    }
  ]
}

{
  "summary": "A sophisticated dual-theme portfolio design that transitions from a light luxury magazine aesthetic to a cinematic tech dark mode, utilizing high-contrast accents and rigorous grid layouts.",
  "style": {
    "description": "The design aesthetic is 'Modern Editorial.' It relies on three distinct font categories: high-contrast serifs for large headlines, clean sans-serif for readable body copy, and monospaced fonts for metadata and technical labels. The color palette is restricted to ivory/onyx foundations with metallic gold highlights. UI elements use thin 1px borders and very subtle radial-gradient background patterns instead of heavy shadows or gradients.",
    "prompt": "Create a UI with a dual-theme system. Light Theme: Background #F9F8F6, Text #111111, Accents #9E7B4F, Borders #E5E0D8, Secondary Text #66615A. Dark Theme: Background #0B0C0E, Text #F3F1EC, Accents #D4AF37, Borders #303139, Secondary Text #A6A6A6. Typography: Headlines in 'Crimson Pro' (weights 300, 400, 600), UI/Body in 'Plus Jakarta Sans' (weights 400, 600), and labels in 'JetBrains Mono' (tracking-widest). Use a 40px radial-gradient dot pattern (opacity 0.2 in light, 0.05 in dark) for hero backgrounds. Borders must be strictly 1px. Transitions should use 0.4s cubic-bezier(0.4, 0, 0.2, 1). Shadows should be minimal (editorial-shadow: 0 4px 30px rgba(0, 0, 0, 0.03))."
  },
  "layout_and_structure": {
    "description": "A multi-section landing page using a fixed navigation bar, asymmetric hero, and modular grid systems for skills and projects. The design favors vertical rhythm and wide margins (max-width: 1280px).",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Fixed 80px height bar with backdrop-blur (80% opacity). Left: Monogram logo in serif bold + uppercase monospaced 'DEVELOPER' label separated by a vertical 1px line. Center: Hidden on mobile, text-xs uppercase links with 0.25em letter spacing. Right: Circular theme toggle (lucide:sun/moon) and a rectangular 'Resume' button with 10px bold uppercase text and wide tracking."
      },
      {
        "part": "Hero Section",
        "prompt": "Asymmetric layout (8:4 grid ratio). Left: Mono label with a horizontal line accent, followed by a massive 8xl serif headline with specific italic highlights for emphasis. Subtext is max-width 24rem. Right: A decorative code-snippet window (w-64 h-96) with thin borders and an L-shaped gold accent bracket in the bottom-left corner."
      },
      {
        "part": "Skills Grid",
        "prompt": "Three-column modular grid where cards are separated by a 1px gap showing the background border color. Each card (p-10) contains a top row with title and icon, followed by specific skill rows with 1px bottom borders. Skill rows include the name on the left and a monospaced proficiency label (e.g., 'Advanced') on the right."
      },
      {
        "part": "Project Gallery",
        "prompt": "Two-column staggered grid. The second card is offset vertically (e.g., mt-24) to create an editorial flow. Cards feature a 16:10 aspect ratio image container with a subtle 700ms scale hover effect. Metadata includes monospaced category labels in gold, a serif title, and GitHub/External icons."
      },
      {
        "part": "Contact Section",
        "prompt": "High-impact section with a inverted theme (dark background even in light mode). Left: 7xl serif headline with 'extraordinary' in light italics. Right: Two-column link list for social and navigation links, with a bottom-aligned copyright and a circular 'Back to Top' arrow button."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Theme Toggle Button",
      "description": "A circular icon button that switches between sun and moon icons with a 0.4s fade and rotation.",
      "prompt": "Button: p-2, rounded-full, transition-colors. Icon: iconify-icon lucide:sun (visible in light) / lucide:moon (visible in dark). Smoothly transition colors of the entire DOM using CSS variables: --bg, --text, --accent, --border."
    },
    {
      "component": "Editorial Project Card",
      "description": "A sophisticated card layout prioritizing typography over heavy containers.",
      "prompt": "Container: group, relative. Image: aspect-[16/10], bg-grey-warm, overflow-hidden, 0.8 opacity. Content: mt-8. Category: font-mono, text-[10px], uppercase, gold-antique. Title: font-serif, text-2xl. Tags: border, text-[9px], font-bold, tracking-widest, px-3, py-1. Hover: Image scales 1.05x, icons change to accent color."
    }
  ]
}

{
  "summary": "A refined, multi-pane LMS dashboard that prioritizes whitespace and readability. It uses a three-column layout (Sidebar, Main Content, Profile/Calendar Sidebar) with high-radius corners (24px-32px) and avoids aggressive left-border accents for a more open feel.",
  "style": {
    "description": "The design uses a vibrant but soft color system: Primary Blue (#0d6efd), Secondary Orange (#f97316), and Success Green (#10b981) against a light-gray background (#f8f9fc). Typography is exclusively 'Plus Jakarta Sans' with a heavy emphasis on bold (700-800) headers and medium (500) muted labels. Micro-interactions include smooth height transitions for charts and subtle shadow-lift on card hover.",
    "prompt": "Create a design system using 'Plus Jakarta Sans'. Main background color is #f8f9fc. Use #ffffff for card surfaces with a 24px border-radius and very light borders (#f3f4f6). Primary text is #1e293b, secondary text is #64748b. Color palette: Blue #0d6efd (Primary), Orange #f97316 (Secondary), Green #10b981 (Success), Pink #ec4899, and Purple #a855f7. Buttons should have 12px border-radius. Shadows should be subtle: 'shadow-sm' for cards and 'shadow-lg shadow-primary/20' for active CTA buttons. Navigation links should use #0d6efd for active states with a rounded vertical indicator pill. Animation: use 'transition-all duration-300' for hover states and 'ease-in-out' for chart bars."
  },
  "layout_and_structure": {
    "description": "A 1440px wide, 3-column application shell with a fixed-height layout (900px) and scrolling internal panels.",
    "prompts": [
      {
        "part": "Left Navigation Sidebar",
        "prompt": "Width: 256px. Background: #ffffff. Border-right: 1px solid #f3f4f6. Includes a logo section with two circular glyphs, an organization selector button (orange background #fff7ed, 12px radius), and vertical navigation links with 12px padding. Bottom section contains a promo card with a gradient (blue-50 to indigo-50) and a floating icon badge."
      },
      {
        "part": "Main Content Area",
        "prompt": "Central fluid column. Background: #f8f9fc. Padding: 32px. Features a header with 3xl font-weight greeting and a pill-shaped search bar (bg-white, rounded-full, px-11). Structure: 1. Stats Row (Vertical stack of icon-left cards), 2. Large Chart Area (2/3 width), 3. Course Grid (3 columns), 4. Assignment Table (Full width)."
      },
      {
        "part": "Right Sidebar (Profile & Activity)",
        "prompt": "Width: 320px. Background: #ffffff. Border-left: 1px solid #f3f4f6. Sections: 1. User Profile (300px circular image, stats list), 2. Mini-Calendar (Horizontal day scroller with active day highlighted in #ec4899), 3. 'Upcoming Class' vertical list, 4. Todo list with custom checkboxes."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Custom CSS Bar Chart",
      "description": "Interactive data visualization with tooltips.",
      "prompt": "Design a bar chart where each bar is a div with 12px radius. Colors vary by data type: #f97316 (orange), #0d6efd (blue), #10b981 (green). Highlighted bars include a floating tooltip at the top (bg-white, shadow-md, bold font, emoji icon). Bars must have a hover state that reveals a dark #111827 tooltip with duration text (e.g., '5h 20m')."
    },
    {
      "component": "Course Joining Card",
      "description": "Thematic entry point with decorative SVG.",
      "prompt": "A 24px rounded card with bg-color #fff7ed. Features an abstract organic blob SVG in the background (color #f97316 at 20% opacity). Includes a white input field wrapper with an embedded CTA button inside the right-hand side of the input (bg-secondary, white text)."
    },
    {
      "component": "Mini Calendar Widget",
      "description": "Horizontal day selector for student schedules.",
      "prompt": "A horizontal row of day-dates. Non-active days: #64748b text. Active day: High-contrast pink background (#ec4899), white text, 12px rounded-xl, vertical offset (-4px transform), and a soft pink shadow."
    }
  ]
}

{
  "summary": "A sophisticated, high-end dark-themed editorial UI characterized by a cinematic 'portal' hero reveal, precision-focused typography pairing (Syne/Sora), and fluid, scroll-driven motion design that bridges luxury aesthetics with modern interactivity.",
  "style": {
    "description": "The style is 'Cinematic Luxury Minimalist'. It uses a primary dark background (#0A0C0E) contrasted with off-white text (#EDE7DC). Typography combines heavy, wide display fonts for headings (Syne) with clean, geometric sans-serifs for body text (Sora). Accents are used sparingly in amber and teal for highlights. Animations are strictly tied to scroll progress and pointer interactions, utilizing cubic-bezier curves for organic feel.",
    "prompt": "Set the global background to #0A0C0E and primary text to #EDE7DC. Use 'Syne' (weights 600, 800) for all headings with -0.03em letter-spacing. Use 'Sora' (weights 400, 600) for body copy. Create a label style: font-size 10.5px, letter-spacing 0.15em, uppercase. Define accent colors: Amber (#E8913C) and Teal (#2E6B72). Implement border hairlines using rgba(237,231,220,0.13). For animations, use cubic-bezier(0.16, 1, 0.3, 1) for reveals. Interactive elements should include a duotone overlay using a 45-degree gradient from Teal to Amber with mix-blend-mode: overlay. All images should have object-fit: cover and object-position: center center."
  },
  "layout_and_structure": {
    "description": "A multi-layered scroll experience starting with a 'Portal Hero' that opens to reveal content, followed by structured grid sections, an interactive card carousel, and a list-based roster with hover reveals.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "A fixed top bar (height 58px) with a backdrop-blur-md and bg-ground/80. Left: Display font wordmark. Right: Links using tracking-wide-label style with amber hover transitions. Border-bottom: 1px hairline."
      },
      {
        "part": "Portal Hero Section",
        "prompt": "A 250vh section with a 100vh sticky stage. The stage contains a background image (#hero-image) initially scaled at 1.1. Over it, two panels (#panel-left and #panel-right) each 50.1% width, meeting at the center. As user scrolls, panels translate horizontally to reveal the image, the image scales down to 1.0, and a central wordmark split in two spans horizontally while scaling up. Two accent dots (Amber and Teal) drift outward from the center during the reveal."
      },
      {
        "part": "Statement Section",
        "prompt": "Full viewport section with bg-groundSec. A 12-column grid. Left 8 columns: teal label, large display heading (text-6xl), and a massive outlined number (e.g., '01') using -webkit-text-stroke: 1px. Right 4 columns: a circular drifting image with mix-blend-luminosity and 40% opacity that rotates and translates based on scroll."
      },
      {
        "part": "Feature Card Deck",
        "prompt": "A split layout. Left: Feature text and primary/secondary CTA buttons. Right: A 'deck' of cards stacked using absolute positioning. Implement a swipe-to-dismiss interaction where the top card (z-index 20) can be dragged horizontally. On dismissal, the card should rotate, fly off-screen, then return to the bottom of the stack with reduced opacity and scale (0.9)."
      },
      {
        "part": "Designer Roster",
        "prompt": "A vertical list of items. Each item has a border-t hairline. On hover: a hidden amber number appears, a grayscale square thumbnail becomes visible and colorized, and the heading text changes to amber. Transition duration: 500ms."
      },
      {
        "part": "Launch Events Table",
        "prompt": "A clean, data-heavy table with tracking-wide-label headers. Rows feature mono-spaced dates and display-font location names. Use amber and teal for status tags (e.g., 'Sold Out', 'On Sale')."
      },
      {
        "part": "Grand Finale Footer",
        "prompt": "A section containing a newsletter signup with a single underlined input. Bottom: A standard footer with social links. Behind everything, place a massive, 24vw font-size wordmark with 10% opacity, partially cut off at the bottom for an editorial look."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Interactive Stacked Deck",
      "description": "A stacked card component that allows users to 'throw' cards away to see the next one.",
      "prompt": "Stack 3 cards with absolute positioning and slight variations in rotation (e.g., -2deg, 3deg, -1deg). Use pointer-events to track X-axis drag. If drag distance > 100px, animate the card out (translate(600px, -100px) rotate(45deg)) and cycle its z-index to the bottom of the stack. Animate the progress bar at the bottom to reflect (currentCardIndex / totalCards)."
    },
    {
      "component": "Portal Wordmark",
      "description": "Typography that splits and scales as the viewport 'opens'.",
      "prompt": "Container uses Syne Extrabold, text-clamp(40px, 12vw, 180px). Wrap words in spans. On scroll, increase letter-spacing and use translateX to push word halves away from the center while scaling the whole container up by 15%."
    }
  ]
}

{
  "summary": "A high-end, professional logistics dashboard design featuring a sapphire and gold color scheme, ivory backgrounds, and card-based data visualization for real-time tracking and account management.",
  "style": {
    "description": "The style is defined by a 'Premium Corporate' aesthetic. Typography uses 'Inter' in varying weights (400-800) to create a clear hierarchy. The color palette centers on #002D72 (Sapphire) for authority, #F9A825 (Golden) for action/highlights, and #FFF8E1 (Ivory) for a softer, premium background feel. Borders are strictly 1px solid #E0DDD6, and card corners are rounded at 16px. Animations are subtle, limited to 200ms ease-in-out transforms and opacity shifts.",
    "prompt": "Create a design system using 'Inter' font. Colors: Primary Sapphire (#002D72), Accent Gold (#F9A825), Success Emerald (#10B981), Link Royal Blue (#1E88E5), Surface Ivory (#FFF8E1), and Border Gray (#E0DDD6). Typography: H2 at 32px (Bold), H3 at 24px (SemiBold), Body at 14px (Regular), and Labels at 11px (Bold Uppercase with 0.1em tracking). UI elements: Cards must have #FFFFFF background, 1px #E0DDD6 border, 16px border-radius, and shadow: 0 1px 2px rgba(0,0,0,0.05). Buttons: Primary is #F9A825 background with #002D72 text, 10px radius, bold; Secondary is #002D72 outline with 2px weight. Interactive states: hover scale 1.02 and 0.9 opacity. Icons: Lucide-style, 24px for headers, 18px for actions."
  },
  "layout_and_structure": {
    "description": "A responsive 2-column bento-grid layout for desktop that stacks into a single column for mobile. Features a fixed top navigation and a mobile-specific bottom tab bar.",
    "prompts": [
      {
        "part": "Header",
        "prompt": "Sticky 64px height header. Background: #FFFFFF, Border-bottom: 1px #E0DDD6. Left: Logo in Sapphire (#002D72) with a 32px icon container. Center: Navigation links ('Send', 'Track', 'Manage') using 14px Inter 600 Sapphire text; active link has a 2px Golden (#F9A825) bottom border. Right: Profile section with a 40px circular avatar and 12px bold uppercase name label."
      },
      {
        "part": "Main Container",
        "prompt": "Max-width 1200px, centered. Background: #FFF8E1. Padding: 32px horizontally, 24px vertically. Layout: Two-column grid with 32px gap between cards."
      },
      {
        "part": "Active Deliveries Widget",
        "prompt": "Full-width or large-column card. Features a top header with H3 title and a 'Track' primary button. Inner 'Highlight' box with #F4F1EC background, 12px radius, showing destination and status pill. Below highlight, a vertical timeline: 2px gray line (#D1D5DB) with 16px circular markers. Markers color-coded: Completed (Emerald #10B981 with check), Active (Golden #F9A825 with arrow), Pending (Gray #D1D5DB)."
      },
      {
        "part": "List Widgets (Quotes/Addresses)",
        "prompt": "Standard card structure. Header with H3 and a 'View All' royal blue link or secondary button. Content: Vertical list of items separated by 1px #E0DDD6 dividers. Each row: 14px bold title, 12px gray secondary text, and a right-aligned pill badge (11px bold uppercase). Hover state for rows: background #F9F8F6."
      },
      {
        "part": "Mobile Navigation",
        "prompt": "Fixed bottom bar 72px height. Background: #FFFFFF, Border-top: 1px #E0DDD6. Four icons evenly spaced: Dashboard, Send, Track, Account. Active state: Royal Blue (#1E88E5), Inactive: Gray (#666666). Labels: 9px bold uppercase."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Status Pill Badge",
      "description": "High-contrast status indicator",
      "prompt": "Pill-shaped container with 6px 12px padding. Typography: 11px Inter 700, Uppercase. Variants: Active (Gold bg, Sapphire text), Quoted (Sapphire 10% opacity bg, Sapphire text), Expired (Gray 30% bg, Gray 600 text), Success (Emerald bg, White text)."
    },
    {
      "component": "Interactive Vertical Tracker",
      "description": "Step-by-step progress indicator for logistics",
      "prompt": "Vertical 2px track. Completed segments in Emerald (#10B981). Active nodes: 16px circle, Golden (#F9A825) with a 4px soft ring (ring-orange-50). Labels: 14px bold for step title, 10px gray for timestamp."
    }
  ],
  "special_notes": "MUST use #FFF8E1 for the page background to avoid a 'sterile' look. DO NOT use vibrant red for errors; prefer muted tones. Ensure all pill badges have tracking-wider (0.05em to 0.1em) for readability. ALL buttons must have a height of at least 44px for mobile accessibility."
}

{
  "summary": "A sophisticated data analytics dashboard design with a heavy focus on motion design and premium UI feedback. It utilizes a 240px fixed sidebar, sticky headers, and a responsive grid of card-based components with soft shadows and large corner radii.",
  "style": {
    "description": "Modern premium aesthetic using 'Discord Blurple' (#5865F2) as the primary brand color and Emerald (#10B981) for success states. Typography relies on Inter for readability and JetBrains Mono for financial/numerical accuracy. The style is defined by smooth cubic-bezier transitions, soft elevation on hover, and animated background gradients.",
    "prompt": "Create a design system using a primary palette of Discord Blurple (#5865F2), Emerald (#10B981), and Slate Grays (#f8fafc to #0f172a). \n\n**Typography:** \n- Body: Inter (Weights: 400, 500, 600, 700). \n- Numbers: JetBrains Mono with `font-variant-numeric: tabular-nums` for data alignment.\n- Headings: Bold Slate-900 with tight tracking.\n\n**Effects:**\n- Border Radius: 24px (cards), 12px (buttons/inputs).\n- Shadows: Light shadow-sm for static cards, elevating to shadow-xl with a colored glow (e.g., #5865F2/5) on hover.\n- Transitions: All interactive elements must use `transition: all 400ms cubic-bezier(0.16, 1, 0.3, 1)`.\n- Background: Subtle animated blobs using blur(120px) with 20% opacity moving in a slow 15s loop.\n\n**Animations:**\n- Entrance: Cards should stagger in using a `fadeInUp` animation (translateY: 20px to 0, opacity 0 to 1) with 100ms delay increments.\n- Counters: Use a 'pop' animation for numbers (`scale(0.95)` to `scale(1)` with a slight blur transition)."
  },
  "layout_and_structure": {
    "description": "A classic dashboard layout with a fixed left-side navigation, a utility-focused top header, and a main content area using a bento-style grid for KPI cards and data visualizations.",
    "prompts": [
      {
        "part": "Sidebar Navigation",
        "prompt": "Fixed 240px width sidebar. White background with a subtle right border (#e2e8f0). Top section features the logo with a 36x36 rounded-xl icon container. Navigation items use 13px font-size, 40ms transitions, and indicate the active state with a left-side 4px thick border in #5865F2 and a light blue tint background. Bottom section contains a bordered currency/rate converter widget."
      },
      {
        "part": "Sticky Header",
        "prompt": "64px height (h-16) white header with 80% opacity and backdrop-filter: blur(12px). Features a search/title section on the left, and utility buttons (notifications, user profile) on the right. The 'Quick Action' button is a bold #5865F2 CTA with a scale-down effect on click (active:scale-95)."
      },
      {
        "part": "KPI Grid",
        "prompt": "Three-column grid of cards. Each card has a 24px internal padding (p-7), a 48x48 icon container in a tinted background (e.g., blue-50 for revenue), and large 30px mono-spaced headings for primary metrics. Include a small badge in the top right for percentage changes (+100% vs last period)."
      },
      {
        "part": "Main Analytics Section",
        "prompt": "A 12-column grid layout where the primary chart takes 8 columns and the rankings take 4. The chart card must feature a time-period selector (7d, 30d, 90d) in a pill-shaped container. Data paths in the SVG chart should animate using `stroke-dashoffset` for a 'drawing' effect over 2.5s."
      },
      {
        "part": "Bottom Insights and Footer",
        "prompt": "Grid of 3 cards for AI-generated insights. Use background tints (Emerald-50, Amber-50, Indigo-50) to differentiate categories (Growth, Alert, Opportunity). The footer is a simple horizontal layout with social icons that scale 125% on hover and copyright text in 11px font."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Shimmering Progress Bar",
      "description": "Interactive ranking bars with a continuous light reflection effect.",
      "prompt": "A 8px height progress bar container with a light gray background. The inner progress bar uses a gradient (e.g., Amber-400 to Amber-500) and an overlay `::after` element with a linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), transparent) that animates from `left: -100%` to `100%` every 2s to create a premium shimmer."
    },
    {
      "component": "Animated SVG Spline Chart",
      "description": "A dual-line chart with interactive tooltips and glowing points.",
      "prompt": "SVG chart with two paths (#5865F2 and #10B981) using `stroke-width: 3.5`. Beneath each line, a linear gradient fill provides a soft 'area' effect. Hovering over a data point shows a 'glass-tooltip' (white, 85% opacity, 12px blur) with detailed tabular metrics. Data points pulse using a 3s ease-in-out scale animation."
    },
    {
      "component": "Pulse FAB",
      "description": "Floating action button with a breathing animation.",
      "prompt": "64x64 fixed button at the bottom-right. Background color #5865F2. Features a surrounding glow achieved via a secondary div with `animate-pulse-soft` (scale 1 to 1.05 and opacity 1 to 0.8). Icon inside rotates 12 degrees on hover."
    }
  ]
}

{
  "summary": "A professional enterprise dashboard in dark mode with a bold gold primary accent (#fac306), technical monospace typography for data, and a clean grid-based architecture for managing complex system entities.",
  "style": {
    "description": "The style is 'Industrial Enterprise Dark'. It uses a deep black (#000000) background with elevated surfaces in zinc grays (#0f0f0f, #1a1a1a). Typography relies on 'General Sans' for hierarchy and 'JetBrains Mono' for technical data points like IDs and status codes. Primary interactions are highlighted with #fac306 (Gold). Visual accents include emerald, red, and blue for status-based color coding. Borders are kept subtle (white/5% opacity) to maintain a sleek, integrated look.",
    "prompt": "Create a pixel-perfect enterprise UI with a background of #000000. Primary accent color is #fac306. Secondary UI elements use Zinc Grays: #0f0f0f (surface), #1a1a1a (elevated), and #262626 (borders). Typography: Use 'General Sans' for headings and body, and 'JetBrains Mono' for all technical IDs, IP addresses, and logs. Headings should be bold with tracking-tight. Buttons have a border-radius of 8px (rounded-lg) and cards have 16px (rounded-2xl). Implement 'glass-panel' effects using background: rgba(15, 15, 15, 0.7) and backdrop-filter: blur(12px). Include a 'gold-glow' shadow effect: box-shadow: 0 0 20px rgba(250, 195, 6, 0.15). Animations: Include a 'status-pulse' effect on indicator dots (scale 0.95 to 1.05, opacity 0.5 to 1.0, 2s infinite). Hover states for cards should include a subtle translateY(-2px) and border-color: rgba(250, 195, 6, 0.3)."
  },
  "layout_and_structure": {
    "description": "A top-down dashboard architecture featuring a fixed glassmorphic header, a high-density bento grid for entity overview, and a hybrid two-column management workspace combining detailed tables with status sidebars.",
    "prompts": [
      {
        "part": "NavigationBar",
        "prompt": "Fixed top navigation, 64px height (h-16), background black/80 with 12px blur. Left section: Logo (shield icon in #fac306 box) and uppercase brand name. Center section: Horizontal nav links with 14px font-size (text-sm) and medium weight, using #a3a3a3 for inactive and white/bg-white/5 for active states. Right section: Status badge (pill-shaped, emerald or gold background-opacity 10%, with pulse icon), notification bell with red dot, and circular avatar (32px)."
      },
      {
        "part": "HeaderSection",
        "prompt": "Breadcrumb-style header area. Left: H1 (30px/text-3xl) bold title with a zinc-500 subtitle below. Right: Flex container with a search input (zinc-900 bg, pl-10 for icon) and a primary 'Create' button (#fac306 bg, black text, bold, uppercase tracking-widest)."
      },
      {
        "part": "EntityGrid",
        "prompt": "Responsive grid (1 col mobile, 4 col desktop) with 24px (gap-6) spacing. Each card: 16px border-radius, zinc-900/40 background. Content includes: Top-left icon (24px) in a colored light-tint box (emerald, blue, or purple), top-right context menu icons, card title (20px bold), short description (line-clamp-2), and a linear progress bar (h-1.5) for status metrics. Bottom of card: flex row showing member counts and a text-link action in gold (#fac306)."
      },
      {
        "part": "ManagementWorkspace",
        "prompt": "Split layout. Left column (2/3 width): Data table in a zinc-900/40 container. Table header: uppercase, 12px bold text, zinc-500. Table rows: subtle hover state (white/2% opacity), 14px font-size, using JetBrains Mono for date/time strings. Right column (1/3 width): Stacked widget area. Widget 1: Access Policy (list of switches/toggles in gold). Widget 2: Audit Trail (vertical timeline with small status dots, using monospace font for timestamps)."
      },
      {
        "part": "FooterStatusBar",
        "prompt": "Fixed height of 32px (h-8), zinc-900 background, border-t white/5%. Text: 10px, bold, uppercase, zinc-600, tracking-widest. Left: flex items for API and engine health with 4px circular status indicators. Right: Version number and legal strings."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Technical Progress Bar",
      "description": "Slim status indicator for resource usage or online percentages.",
      "prompt": "A container with h-1.5, bg-zinc-800, and rounded-full. The active fill should use high-saturation colors (Emerald #10b981 or Gold #fac306) and have a subtle outer glow shadow matching its color."
    },
    {
      "component": "Policy Toggle",
      "description": "A custom enterprise-style switch for dashboard permissions.",
      "prompt": "A rounded-full container 40px wide, 20px high (w-10 h-5). Active state: bg-#fac306 with a black circular knob (12px) positioned 4px from the right. Inactive state: bg-zinc-700 with a zinc-500 knob positioned 4px from the left."
    },
    {
      "component": "Status Pulse Dot",
      "description": "Animated indicator for live connections.",
      "prompt": "A 6px circular div (w-1.5 h-1.5) with absolute border-radius-full. Background color matches the status (Emerald for online, Red for alert). CSS Animation: pulse 2s ease-in-out infinite (0% {transform: scale(0.95); opacity: 0.5;} 50% {transform: scale(1.05); opacity: 1;} 100% {transform: scale(0.95); opacity: 0.5;})."
    }
  ]
}

{
  "summary": "A sophisticated enterprise management interface utilizing a dark theme with vibrant gold accents, featuring modular data visualization, dense information tables, and technical typography for high-precision monitoring.",
  "style": {
    "description": "The 'SecretX' style essence is defined by its deep obsidian backgrounds (#000000) and layered translucent panels (rgba(15, 15, 15, 0.7)). It employs a 'Cyber-Industrial' aesthetic with a primary gold accent (#fac306) used for high-priority UI elements and status indicators. Typography is hierarchical: General Sans for UI headers and body text, while JetBrains Mono provides a technical feel for IDs, IPs, and code-like data. Micro-interactions include a rhythmic 'status-pulse' animation for active connections and a 'gold-glow' shadow effect for critical focus areas.",
    "prompt": "Create a pixel-perfect design system based on a Dark Enterprise theme. \n- **Color Palette**: Primary Gold (#fac306), Pure Black (#000000), Surface Dark (#0f0f0f), Surface Elevated (#1a1a1a), Border Color (#262626), Secondary Text (#a3a3a3), and Emerald (#10b981) for success states.\n- **Typography**: Primary Font: 'General Sans' or 'Inter' (300, 400, 500, 600, 700 weight). Secondary Technical Font: 'JetBrains Mono' for serial numbers, IP addresses, and timestamps.\n- **Layout Components**: Glassmorphism panels using backdrop-filter: blur(12px) and 1px borders (#262626). Rounded corners at 16px (2xl) for cards and 8px (lg) for interactive elements.\n- **Animations**: A 'status-pulse' keyframe (0% { transform: scale(0.95); opacity: 0.5; } 50% { transform: scale(1.05); opacity: 1; } 100% { transform: scale(0.95); opacity: 0.5; }) applied to status dots. Smooth transitions (300ms cubic-bezier(0.4, 0, 0.2, 1)) for hover states.\n- **Shadows**: Use a custom gold glow: 'box-shadow: 0 0 20px rgba(250, 195, 6, 0.15)' for elevated gold elements."
  },
  "layout_and_structure": {
    "description": "The interface follows a tiered hierarchy: a fixed 64px top navigation bar, a high-level statistical overview grid, and a split-view content area comprising a fixed-width sidebar for filtering and a flexible main table for data management.",
    "prompts": [
      {
        "part": "Navigation Bar",
        "prompt": "Design a fixed top navigation (h-16) with 80% opacity black background and backdrop-blur. Include a left-aligned logo (8x8 gold square icon with black vector), a centered flex-row of links (text-sm, Zinc-400, hover:white), and a right-aligned profile section including a status pill ('Server: Online') with a pulsing gold dot."
      },
      {
        "part": "Hero Header",
        "prompt": "Create a page header with a max-width of 1600px. Left side: Display a category label in gold (#fac306) text-xs uppercase tracking-widest, followed by a H1 (text-4xl, bold, tracking-tight). Right side: Place a button group including a secondary Zinc-900 border button and a primary Gold (#fac306) solid button with a plus-circle icon and bold text."
      },
      {
        "part": "Statistical Grid",
        "prompt": "Implement a 5-column grid (responsive to 2 and 4 columns). Each card should have a 1px border (#white/5), 20px padding, and 16px corner radius. Feature a large icon (left) and status label (right) on the top row, with a large bold value (text-3xl) and descriptive label (text-xs uppercase Zinc-500) below. Include a P2P connectivity card with a mini-progress bar (h-1, gold fill)."
      },
      {
        "part": "Filter Sidebar",
        "prompt": "A 280px sidebar containing vertical filter groups. Group headers: text-xs bold uppercase tracking-widest in Zinc-500. Filter items: Flexbox layout with text-sm labels and technical counts (JetBrains Mono). Include custom checkbox inputs accented in Gold (#fac306). Add a security warning box at the bottom (bg-red-500/5, border-red-500/10) for alerts."
      },
      {
        "part": "Data Management Table",
        "prompt": "A dense interactive table with themed styling. Header: black/40 background, text-10px bold uppercase Zinc-500. Body: Divide rows with #white/5 borders. Each row features a 40x40 icon container with a status dot overlay. Include performance columns with mini-sparkline progress bars (h-1) for CPU/RAM usage. Action column: Fixed-width right-aligned group with a primary gold 'CONNECT' button and a three-dot menu icon."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Enterprise Auth Modal",
      "description": "A high-security login overlay with glassmorphism and gold accents.",
      "prompt": "Design a fixed overlay (bg-black/95) containing a max-w-md card (bg-zinc-900). Center a large gold square logo. Use input fields with bg-zinc-950 and border-white/10 that transition to border-gold (#fac306) on focus. Primary button: full-width, bg-gold (#fac306), black text, bold, with active:scale-95 transform. Include SSO options for Entra ID and Google with icon/label pairings."
    },
    {
      "component": "Performance Sparkline",
      "description": "Minimalist resource usage indicator for tables.",
      "prompt": "Create a compact performance indicator. Top row: Label (e.g., CPU) left, value (e.g., 24%) right in text-[9px] bold uppercase. Bottom row: 4px height track (bg-zinc-950) with a colored fill (bg-gold or bg-red for high usage) representing the percentage width."
    }
  ]
}

{
  "summary": "A sophisticated dark-mode conversational UI with a focus on technical clarity, featuring a monochromatic palette, rounded corner aesthetics (16px), and high-density information layout for AI agent feedback and history tracking.",
  "style": {
    "description": "The style is defined by a deep dark theme using #0a0a0a as the foundation. It relies on varying border shades (#222 to #444) for depth rather than shadows. Typography uses 'General Sans' for a modern, geometric look, paired with 'JetBrains Mono' for technical outputs. Micro-interactions utilize a consistent 0.3s cubic-bezier(0.4, 0, 0.2, 1) transition for all hover states.",
    "prompt": "Create a design system with a base background of #0a0a0a and text in #e8e8e8. Use 'General Sans' as the primary font and 'JetBrains Mono' for technical details. Headings should be 12px uppercase with 0.2em tracking in #666. Primary UI borders should be 1px solid #222. Interactive elements like cards should transition to a #444 border on hover with a 0.3s cubic-bezier animation. Buttons should use high contrast: a primary white/near-white (#e8e8e8) background with dark text (#0a0a0a) for primary actions, and transparent backgrounds with #222 borders for secondary actions. Use a 16px (1rem) corner radius for containers and input fields."
  },
  "layout_and_structure": {
    "description": "A fixed header and footer layout with a flexible, scrollable main content area. The structure toggles between an 'empty state' dashboard view and an 'active chat' view.",
    "prompts": [
      {
        "part": "Header",
        "prompt": "Height: auto, with pt-14 px-6 pb-4. Border-bottom: 1px solid #222. Left side: 40x40px circular back button with a 20px icon centered. Right side: 32x32px circular avatar with a linear-gradient(to top right, #333, #555) and a 1px border (#444)."
      },
      {
        "part": "Dashboard Empty State",
        "prompt": "A vertical stack of 'Recent Conversations'. Includes a section title: 12px, uppercase, 0.2em tracking, color #666. Conversation cards: 16px corner radius, background #111 (for active/recent) or #0a0a0a, border #222, padding 16px. Card title: 14px font-medium. Card preview text: 13px, color #999, single line clamp."
      },
      {
        "part": "Active Chat Area",
        "prompt": "Scrollable flex-1 area with 32px gap between message blocks. User messages: Right-aligned, max-width 85%, background #222, border #333, 16px padding, 16px radius with top-right corner set to 0. AI messages: Left-aligned, includes a sequence of execution steps in 13px #888 (e.g., '1. Initializing...'), followed by main response text in 15px #e8e8e8 with 1.625 line-height and list items with 8px spacing."
      },
      {
        "part": "Footer Input",
        "prompt": "Fixed at bottom, pb-34px px-4. Contains a relative container for the text input. Input: background #111, border #222, 16px radius, height 56px, pl-20px pr-56px. Send button: Absolute positioned at right-8px, 40x40px, 12px radius, background #e8e8e8, color #0a0a0a. Icon: 20px centered."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Interactive Conversation Card",
      "description": "A sophisticated list item with subtle state changes.",
      "prompt": "Create a card with padding: 16px; border-radius: 16px; border: 1px solid #222; background: #0a0a0a. On hover, background transitions to #111 and border to #444. Inside, place a 14px medium weight title and a 13px light gray (#999) preview text truncated to one line."
    },
    {
      "component": "Agent Execution Log",
      "description": "Subtle status indicators for AI processing steps.",
      "prompt": "Use a vertical stack of text lines in 13px #888. Each line starts with a number (e.g., '1. ', '2. '). This block should appear before the main AI response to indicate background tasks, separated by 16px from the main message body."
    }
  ],
  "special_notes": "Must-dos: Ensure all icons are consistent (Lucide/Iconify style). Maintain absolute black (#0a0a0a) for the body to ensure high contrast. Use 'General Sans' for the interface to maintain a 'premium tech' feel. Must-nots: Avoid using standard blue links; use white or high-contrast grays. Do not use standard drop shadows; define depth through border color increments."
}

{
  "summary": "A clean, dark-themed AI chat interface that prioritizes text readability and minimal UI friction. It features a high-contrast monochromatic color scheme, subtle border-based containers for user input, and an open, borderless layout for AI-generated content to create an integrated document-like experience.",
  "style": {
    "description": "The style is defined by its 'Tech-Noir' minimalism. It uses a base background of #0A0A0A, paired with structural borders in #222 and #333. Typography pairs the sleek 'General Sans' for headers/body with 'JetBrains Mono' for technical tasks and 'Inter' for UI labels. The color palette is strictly monochromatic: #0A0A0A (background), #111 (secondary surfaces), #222 (borders), #E8E8E8 (primary text/accents). Animations are smooth, utilizing cubic-bezier(0.4, 0, 0.2, 1) for all hover and state transitions.",
    "prompt": "Create a high-fidelity dark mode UI. Background: #0A0A0A. Primary Text: #E8E8E8 (Inter or General Sans). Secondary Text: #999 or #666. Typography: Body text at 15px with 1.6 leading; Subheadings at 12px, 0.2em letter-spacing, uppercase, font-weight 600. Borders: 1px solid #222 or #333. Corner Radius: 16px (2xl) for cards and inputs. Buttons: Primary action buttons should use #E8E8E8 background with #0A0A0A text. Transitions: all 0.3s cubic-bezier(0.4, 0, 0.2, 1). Icons: Use Lucide-style thin-stroke icons in #888 or #E8E8E8."
  },
  "layout_and_structure": {
    "description": "The layout is a single-column mobile-first design with a sticky header and footer. It transitions between an 'Empty/Recent' state and an 'Active Chat' state.",
    "prompts": [
      {
        "part": "Header",
        "prompt": "Fixed top header with 56px height (pt-14, pb-4). Includes a 40x40px circular back button (#222 hover) on the left and a 32x32px gradient-fill user avatar (from #333 to #555) on the right. Bottom border: 1px solid #222."
      },
      {
        "part": "Recent Conversations List",
        "prompt": "A vertical stack of conversation cards. Each card: 16px padding, 16px border-radius, background #0A0A0A, border 1px solid #222. Title: 14px Medium weight. Preview text: 13px, #999, single line clamp. Active/Highlighted card uses background #111. Hover effect: border changes to #444."
      },
      {
        "part": "Active Chat Feed",
        "prompt": "A scrollable area with 32px vertical gaps between message blocks. User messages: Right-aligned, max-width 85%, background #222, border 1px solid #333, text 14px, rounded-2xl with bottom-right corner squared (rounded-tr-none). AI messages: Left-aligned, no background, no border, no padding. Includes an 8x8px square bot icon in #111 container. AI content flows as standard typography with 16px paragraph spacing and 8px list item spacing."
      },
      {
        "part": "Thought Process / Steps",
        "prompt": "Before the AI text response, include a list of 'agent steps' in #888 text color, 13px size, JetBrains Mono font. Each step should appear on a new line to simulate real-time processing logs."
      },
      {
        "part": "Input Footer",
        "prompt": "Fixed bottom bar with 34px bottom padding. Centered input container with 1px border #222, background #111, 16px border-radius. Input text: 14px, #E8E8E8. Right-aligned action button: 40x40px, rounded-xl, background #E8E8E8, text #0A0A0A, containing a horizontal send icon."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Borderless AI Response",
      "description": "A clean text block for AI output that avoids the 'chat bubble' look.",
      "prompt": "Display AI response as raw text within the flex container. Text color: #E8E8E8. Font size: 15px. Line height: 1.6. Use a 20px bottom margin for paragraphs. Bold text within responses should use #FFFFFF and 600 weight. Use standard disc bullets for lists with a 20px left indentation."
    },
    {
      "component": "Bento Conversation Card",
      "description": "Minimalist list item for recent history.",
      "prompt": "A container with background #111, border #222, 16px padding, and 16px radius. Includes a 14px title and a 13px #999 description. On hover, the border transitions to #444 with a cubic-bezier ease."
    }
  ]
}

{
  "summary": "A minimalist historical-themed mobile interface that mimics the look of high-quality parchment and antique stationery. It features large, editorial serif headings, thin-lined UI components, and a specific 'paper sheet' layout that slides over a warm beige background.",
  "style": {
    "description": "The style essence is 'Modern Archive'—warm, tactile, and legible. It avoids gradients and shadows in favor of 1px borders and flat color blocks. Typography uses 'Crimson Pro' (Serif) for character and 'Manrope' (Sans) for functional data. The color palette is strictly limited to cream, beige, and bronze-gold.",
    "prompt": "Create a design with a warm, historical-minimalist aesthetic. Use a primary background of #EDE7D8. Overlay this with a 'paper sheet' container in #FBF8F1 featuring a 40px top-border radius. Typography: Headings in 'Crimson Pro' or 'Playfair Display' (Bold, 60px, #3D352E); Body and UI labels in 'Manrope' (400-700 weight, #3D352E). Accent color: #A5812F (used for borders, active states, and icons). Buttons must be transparent with a 1px solid border (#A5812F) and 4px corner radius. Micro-interactions: Use 0.2s cubic-bezier ease-out for hover and active scale effects. Icons should be thin-line style (Lucide/Linear style) in #A5812F or #8C8276."
  },
  "layout_and_structure": {
    "description": "A vertical mobile layout (393x852) structured into a header area, a sliding paper main content area, and a fixed bottom navigation bar.",
    "prompts": [
      {
        "part": "Header Area",
        "prompt": "Top padding of 48px, horizontal padding of 24px. Top-aligned metadata row using 11px uppercase tracking-widest text (#8C8276). A settings icon (24px) aligned to the right. A massive 60px Serif H1 title followed by a 16px medium-weight subtitle in #8C8276. The header sits directly on the #EDE7D8 background."
      },
      {
        "part": "Main Paper Content",
        "prompt": "A container with background #FBF8F1 and top-rounded corners (40px). Vertical padding starts at 40px. This area houses all primary functional content like lists and interaction bubbles. The shadow should be subtle: 0px -4px 20px rgba(0,0,0,0.03)."
      },
      {
        "part": "Shop Inventory List",
        "prompt": "Vertical list of items separated by 1px solid lines (#E5DFD0). Each row has 20px top/bottom padding. Layout: Left side contains a 40px square rounded icon box (#F4F0E6) and text block (14px Bold Uppercase title, 12px muted subtitle). Right side contains the minimalist price button."
      },
      {
        "part": "Bottom Navigation Bar",
        "prompt": "Fixed bar with background #FBF8F1, height approx 80px. 1px top border (#E5DFD0). Five items distributed evenly. Active state: color #A5812F with a 2px horizontal indicator bar positioned 16px above the icon. Text labels: 11px uppercase, 0.05em letter spacing, centered under 24px icons."
      },
      {
        "part": "Floating Action Button",
        "prompt": "A 56x56 circular button in #A5812F. Centered white icon (24px). Positioned 24px from the right and 96px from the bottom. Includes a standard elevation shadow."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Minimalist Price Button",
      "description": "A transparent, bordered button for transactional actions.",
      "prompt": "Border: 1px solid #A5812F. Padding: 4px 10px. Radius: 4px. Text: 15px Bold #A5812F. Includes a small 14px icon trailing the text with a 4px gap. Background is transparent, changing to rgba(165, 129, 47, 0.05) on hover."
    },
    {
      "component": "Character Quote Bubble",
      "description": "An asymmetrical speech bubble for mascot hints or quotes.",
      "prompt": "Background: #F4F0E6. Padding: 12px 16px. Border Radius: 20px 20px 20px 0px (bottom-left corner is sharp). Text: 14px Italic #3D352E with leading-relaxed. Paired with a 48px circular avatar to the left."
    }
  ],
