{
  "summary": "A dark, architectural design system with industrial accents and high-end editorial typography. It features a cinematic scroll-revealed hero section and a physics-inspired draggable card interface.",
  "style": {
    "description": "The style is built on a high-contrast dark palette (#0A0C0E) with parchment-colored ink (#EDE7DC) and industrial accents in amber (#E8913C) and deep teal (#2E6B72). Typography pairs the geometric Syne for bold display use with the clean Sora for technical metadata. Animations are heavy on scroll-linked transforms, panel-splitting transitions, and physics-based card dragging with cubic-bezier curves.",
    "prompt": "Create a design system using a dark mode palette: background #0A0C0E, primary ink #EDE7DC, secondary ink #9EA5A8, and hairline borders rgba(237, 231, 220, 0.13). Use an accent color of Amber #E8913C. Typography: Use 'Syne' (weights 600, 800) for all display headings with -0.03em letter-spacing; use 'Sora' for body and metadata. Metadata labels should be 10.5px, uppercase, with 0.15em letter-spacing. UI components must feature 1px hairline borders and subtle backdrop blurs (14px). Micro-interactions should use cubic-bezier(0.2, 0.8, 0.2, 1) for smooth, natural movement. Incorporate duotone overlays using a teal-to-amber gradient mix-blend-overlay."
  },
  "layout_and_structure": {
    "description": "A vertically-stacked layout prioritizing immersive scroll experiences, including a 'portal' hero that splits open, editorial text folds with parallax floating elements, and a dynamic interactive catalog.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Fixed header at 58px height. Background is rgba(10, 12, 14, 0.7) with a 14px backdrop blur. Include a bottom border of 1px rgba(237, 231, 220, 0.13). The logo uses Syne Extra Bold. Navigation links use Sora 10.5px uppercase with wide tracking. CTA button is a pill-shape outline with a full-fill hover transition."
      },
      {
        "part": "Portal Hero Section",
        "prompt": "A 250vh scroll stage containing a sticky 100vh viewport. Two panels (Left/Right, each 50.5% width) split horizontally during scroll to reveal a background video. The background video scales from 1.15 to 1.0. A central title (Syne Black) splits into two halves that translate outward as the user scrolls. Add two 4px amber accent dots that move from the center to opposite corners along a 45-degree axis."
      },
      {
        "part": "Statement Fold",
        "prompt": "Full-height section with a large display heading (clamp 24px-52px). Include a large, ghosted background number (e.g., '01') using -webkit-text-stroke. Feature a floating circular image (384px x 384px) that rotates and parallaxes vertically on scroll, featuring a grayscale filter and a thin hairline border."
      },
      {
        "part": "Interactive Catalog Deck",
        "prompt": "Two-column layout. Left column: editorial text with a teal-bordered CTA. Right column: A stack of three cards in a 3D perspective container. Cards should be draggable/throwable using physics logic. When a card is dragged beyond a 20% width threshold, it should animate off-screen with rotation and opacity loss. Below the deck, include a progress bar (1px height) that reflects the active card index."
      },
      {
        "part": "Roster and Schedule List",
        "prompt": "A technical list layout. List items feature hover states with background color #101317 and top borders. Data tables use a 4-column grid (Date, Artist, Venue, City) with Sora typography. Venue information is hidden on mobile."
      },
      {
        "part": "Wordmark Footer",
        "prompt": "A tall footer with industrial spacing. Top section includes a subscription area with an amber-bordered button. Bottom section contains a triple-column legal row (8px font). The final element is a massive, background-style Syne wordmark ('ARGOS') at 20vw font-size, partially cut off at the bottom for an editorial look."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Throwable Card Deck",
      "description": "A physics-based interactive stack of cards.",
      "prompt": "Cards are stacked with initial rotations (e.g., -4deg, 2deg, -1deg). On mousedown/touch, the top card follows the cursor with a 0.1x rotation factor relative to horizontal displacement. On mouseup, if displacement is >20% of container width, the card 'throws' to the side (translateX 1000px, -200px translateY, 90deg rotation). If threshold isn't met, card snaps back to center using cubic-bezier(0.2, 0.8, 0.2, 1)."
    },
    {
      "component": "Scroll-Split Wordmark",
      "description": "Headline that breaks apart as the user opens the portal.",
      "prompt": "The headline is split into two spans. As the user scrolls, the total scale of the title container increases from 1 to 1.4, while letter-spacing decreases from -0.03em to -0.18em. Simultaneously, the two spans translate horizontally away from each other (up to 150px each)."
    }
  ]
}

{
  "summary": "A warm, editorial mobile dashboard design termed 'Mediterranean Editorial'. It uses a cream paper background, dark ink typography, terracotta accents, and a blend of refined serif display fonts with clean functional sans-serif for data.",
  "style": {
    "description": "The style essence is 'Tactile Minimalist' or 'Modern Editorial'. It mimics physical paper textures through specific color choices (#FAF7F2 background) and ultra-thin borders. Typography is a critical anchor, pairing the sophisticated serif 'Fraunces' for brand and headers with 'Plus Jakarta Sans' for utility. Animation is subtle, focusing on color shifts and slight shadow transitions.",
