{
  "summary": "A dark-mode neumorphic design system utilizing dual-tone shadows (light/dark) to create extruded and inset surfaces, paired with high-performance typography and vibrant accent colors for technical SaaS applications.",
  "style": {
    "description": "The style is defined by its 'Tactile Dark' aesthetic. It uses DM Sans for readability, Plus Jakarta Sans for high-energy headings, and JetBrains Mono for data. Surfaces are never flat; they are either 'extruded' (raised) or 'inset' (depressed). Color is used sparingly but purposefully: Amber (#F59E0B) for primary actions and Teal (#38B2AC) for success states or versioning. Transitions use a sharp cubic-bezier (0.4, 0, 0.2, 1) to feel responsive and mechanical.",
    "prompt": "Create a dark neumorphic UI with a background of #151A28 and surface cards of #1F2A3A. Implement two distinct shadow types: 1. Extruded: '8px 8px 12px rgba(0, 0, 0, 0.5)' and '-8px -8px 12px rgba(255, 255, 255, 0.12)'. 2. Inset: 'inset 6px 6px 8px rgba(0, 0, 0, 0.5)' and 'inset -6px -6px 8px rgba(255, 255, 255, 0.12)'. Borders should be '1px solid rgba(245, 158, 11, 0.25)'. Typography: Headings in Plus Jakarta Sans (ExtraBold), Body in DM Sans, and technical data in JetBrains Mono. Use #F59E0B for brand accents and #38B2AC for secondary data. Buttons must shift from extruded to inset on :active state with a 2px vertical translate."
  },
  "layout_and_structure": {
    "description": "Modular and scalable layout using a flexible bento grid for information hierarchy. The structure flows from high-level branding and actions down to granular technical controls and data grids.",
    "prompts": [
      {
        "part": "Header",
        "prompt": "Large branding area with title in font-size 48px, weight 800 (Plus Jakarta Sans). Include a distinct colored period/dot at the end. Right-aligned navigation should feature square 48x48px buttons with 16px border-radius and extruded neumorphic shadows."
      },
      {
        "part": "Action Components & Tabs",
        "prompt": "Two-column section. Left: Primary CTA buttons with 16px padding and 20px border-radius. Search bar with inset shadow and left-aligned icon. Right: Segmented tab navigation where the container is inset and the active tab is extruded with an accent background."
      },
      {
        "part": "Form Controls",
        "prompt": "A dedicated grid for technical inputs. Include labels in uppercase, 10px font-size, tracking-widest. Inputs should be inset rectangles with 16px border-radius. Group controls like counter buttons (minus/plus) alongside an inset value display."
      },
      {
        "part": "Bento Module Catalog",
        "prompt": "Three-column grid of cards. Cards feature 32px border-radius, extruded shadows, and #1F2A3A background. Each card contains a 48px square inset icon container, a bold title, and a footer with a technical version string in JetBrains Mono and a hover-triggered arrow animation."
      },
      {
        "part": "Operational Data Grid",
        "prompt": "Full-width table housed within an extruded 32px radius container. Header row should be 50% opacity background. Cells feature mono-font IDs and status badges (low-opacity backgrounds with high-opacity text). Footer includes pagination using a mix of inset and extruded square buttons."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Neumorphic Selection Controls",
      "description": "Custom checkboxes and radios that look like physical switches.",
      "prompt": "Checkbox: 24x24px, 6px radius, inset shadow background. When checked, background fills with #F59E0B and shows a white checkmark. Radio: 24x24px, 50% radius, inset shadow. When checked, displays a 10px solid #F59E0B center dot. Toggle: 48x24px pill shape with inset shadow, featuring a sliding circular knob that moves 24px and changes color when active."
    },
    {
      "component": "File Drop Zone",
      "description": "Interactive dashed upload area.",
      "prompt": "2px dashed border using rgba(245, 158, 11, 0.25). Inset background #151A28. Hover state should change border to #F59E0B and add a subtle 5% opacity tint to the background. 32px border-radius."
    },
    {
      "component": "Tactile Modal",
      "description": "High-focus overlay with extreme blur.",
      "prompt": "Backdrop: rgba(10, 12, 18, 0.85) with 8px backdrop-filter blur. Modal: 32px border-radius, background #1F2A3A, heavy extruded shadow. Footer buttons must span equal widths with one primary extruded action and one secondary inset action."
    }
  ],
  "special_notes": "MUST maintain the specific dual-shadow values to achieve the neumorphic effect; single shadows will break the style. MUST NOT use pure black or pure white for backgrounds. MUST use JetBrains Mono for all numeric or path-based data. MUST ensure all interactive elements have a visible 'inset' state change on click/active."
}

{
  "summary": "A professional editorial catalog system featuring a deep noir theme (#050505), high-contrast off-white typography (#F5F5F2), and a signature grain-textured glassmorphism. It uses a blend of sans-serif for headlines and monospaced fonts for technical data, resulting in a 'tech-noir' aesthetic that feels precise and premium.",
  "style": {
    "description": "Editorial Noir aesthetic using Instrument Sans for primary text and IBM Plex Mono for metadata. Color palette relies on a nuanced scale of blacks and greys. Key elements include a 6% opacity noise grain overlay, 20px backdrop blurs on sticky surfaces, and -0.06em tracking on large headlines for an editorial look.",
    "prompt": "### Visual Style Guide\n- **Color Palette**: \n  - Canvas: `#050505` (Primary background)\n  - Surfaces: `#0A0A0A` (Raised), `#111111` (Soft), `#181818` (Strong)\n  - Dividers: `#282828` (Quiet), `#3A3A3A` (Strong)\n  - Typography: `#F5F5F2` (Primary), `#B8B8B3` (Secondary), `#74746F` (Muted)\n\n- **Typography**:\n  - **Headlines**: 'Instrument Sans', weights 600-700. Features: `letter-spacing: -0.06em`, `line-height: 0.95`.\n  - **Body/UI**: 'Instrument Sans', weights 400-500. `font-size: 15px` or `16px`.\n  - **Data/Labels**: 'IBM Plex Mono', weight 500. `text-transform: uppercase`, `letter-spacing: 0.08em`, `font-size: 11px`.\n\n- **Visual Effects**:\n  - **Grain**: Apply a fixed overlay using an SVG `feTurbulence` (baseFrequency 0.65) at 6% opacity with `mix-blend-mode: soft-light`.\n  - **Glassmorphism**: `background: rgba(10, 10, 10, 0.85)`, `backdrop-filter: blur(20px)`, combined with a subtle internal noise texture (10% opacity).\n  - **Underlining**: Custom emphasis using a pseudo-element: `height: 4px`, `background: #B8B8B3` at 40% opacity, rotated `-0.5deg`, positioned behind text.\n\n- **Animations**:\n  - **Transitions**: 150ms ease for hover states; 200ms ease for layout expansions.\n  - **View Transitions**: Enable `navigation: auto` for seamless page morphing."
  },
  "layout_and_structure": {
    "description": "A vertically stacked layout with sticky navigation and toolbars, leading into a multi-column catalog grid. The architecture prioritizes data clarity and quick filtering.",
    "prompts": [
      {
        "part": "Sticky Header",
        "prompt": "Height: 72px. Surface: Glassmorphism (#0A0A0A at 85% with 20px blur). Bottom border: 1px solid #282828. Contains brand ID and primary navigation items."
      },
      {
        "part": "Editorial Hero Section",
        "prompt": "Vertical padding: 96px. Contains a single, large-scale headline using `clamp(52px, 6.2vw, 84px)`. Max-width: 1200px. Background features a 1px solid #282828 bottom border."
      },
      {
        "part": "Sticky Search Toolbar",
        "prompt": "Height: auto, typically 72px-80px. Background: Glassmorphism. Position: Sticky at top 72px. Contains a search input with icon and secondary 'Filters' button. Spacing: 24px gap between elements."
      },
      {
        "part": "Main Catalog Grid",
        "prompt": "Structure: Two-column layout (240px sidebar / 1fr main). Sidebar contains category links with 12px vertical padding and 500-600 weight typography. The main container utilizes a repeating row-based grid."
      },
      {
        "part": "Catalog Row Item",
        "prompt": "Grid Template: `80px 280px 180px 120px 120px 100px 1fr 40px`. Padding: 24px vertical. Border-bottom: 1px solid #282828. Features: `image-stage` (4:5 aspect ratio, #181818 bg, 12px radius), monospaced technical values, and hover transitions for color brightness."
      },
      {
        "part": "Comparison Dock",
        "prompt": "Fixed at bottom: 40px from edge. Style: Glassmorphism container with `rounded-[20px]`, `border: 1px solid rgba(255,255,255,0.1)`, and heavy shadow `shadow-[0_24px_80px_rgba(0,0,0,0.8)]`. Layout: Horizontal flex with visual slots for selected items and a primary action button."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Expanding Detail Panel",
      "description": "A nested information area that reveals high-density technical specifications.",
      "prompt": "Background: `#0A0A0A`. Border-radius: 20px. Padding: 48px. Contents: Two-column grid (50/50). Left column: Data table with rows separated by 1px solid #282828 dividers, using monospaced values. Right column: Documentation summary with a `btn-primary` call-to-action."
    },
    {
      "component": "Action Buttons",
      "description": "Distinctive button styles for hierarchy.",
      "prompt": "Primary: Background #F5F5F2, Color #050505, Weight 600, Radius 10px. Action/Secondary: Transparent background, Border 1px solid #3A3A3A, Color #B8B8B3, Font: IBM Plex Mono 11px. Hover state for Secondary: Background #181818, Border #74746F, Color #F5F5F2."
    }
  ]
}

{
  "summary": "A sophisticated digital magazine design system with an editorial 'Dark Forest' aesthetic, combining high-contrast typography, organic paper textures, and structured bento-grid components for a premium storytelling experience.",
  "style": {
    "description": "The style is characterized by its 'Dark Forest' (#0a2f17) and 'Cream' (#faf5e6) foundations, accented by 'Gold' (#eebc4a). It uses a heavy noise/paper grain texture (SVG fractal noise) to simulate high-quality print. Typography relies on the high-contrast Fraunces serif for expressive headlines and Inter for functional UI elements. Layouts utilize deep shadows (0 50px 100px -20px rgba(0,0,0,0.15)) and large border radii (2.5rem) to create a contemporary 'soft-brutalist' editorial feel.",
    "prompt": "Apply a design system based on a high-end editorial magazine. Colors: primary background 'Forest Green' (#0a2f17), secondary background 'Cream' (#faf5e6), primary accent 'Gold' (#eebc4a), secondary accent 'Muted Gold' (#b28a3c), and 'Mint' highlights (#e8f3ec). Typography: Use 'Fraunces' (serif, weights 400-900) for headlines with letter-spacing -0.02em; use 'Inter' (sans-serif, weights 400-900) for body and metadata. UI Elements: Container border-radius at 2.5rem (40px); large, soft shadows (rgba(0,0,0,0.15)); and thin borders (1px) at 10% opacity white or forest. Implement a 'Paper Grain' overlay using an SVG filter (feTurbulence baseFrequency='0.65' at 0.04 opacity). Animations: Smooth 105% scale on hover for buttons, subtle rotation (-2deg) on featured images, and view-transitions for page navigation."
