    {
      "component": "Paper Grain Overlay",
      "description": "SVG-based texture for tactile feel.",
      "prompt": "Absolute position fill; opacity 0.04; pointer-events none; background-image using feTurbulence fractalNoise baseFrequency 0.65; z-index high."
