      },
      {
        "part": "Explore Platform Modules",
        "prompt": "A 4-column bento-style grid. Each module is a clickable card with a 1px border. Elements per card: 24px Lucide-style icon, 14px semibold title, and 11px leading-relaxed description. Hover state: Border changes to blue and title text color shifts."
      },
      {
        "part": "Final CTA & Footer",
        "prompt": "CTA: Centered 36px bold text with a 100px vertical blue gradient overlay. Two large action buttons: 'Get Started' (solid blue) and 'Talk to Expert' (outlined). Footer: Low-profile with system logo on the left and a monospace 'Current System Time' display in UTC on the right."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Operational Status Badge",
      "description": "A high-visibility status indicator for real-time monitoring.",
      "prompt": "Create a status badge component: Monospace text, 9px-10px size, uppercase. Background: 10% opacity of accent color. Border: 20% opacity of accent color. Text: 100% opacity of accent color. Example: Green badge with '91% HIGH CONFIDENCE' or 'SYNCHRONIZED'."
    },
    {
      "component": "Incident Overlay Card",
      "description": "Floating glassmorphism-style info cards found in the hero map.",
      "prompt": "Design a floating card: Background `#080A0D` at 90% opacity, backdrop-blur 10px. Padding 16px. Top-right corner displays a system ID in 8px gray monospace. Include a horizontal progress bar for 'Confidence' using a 4px height background track and a full-intensity accent color fill."
    }
  ]
}

{
  "summary": "A high-contrast, dark-mode design system with a futuristic 'cyber-luxury' feel. It utilizes deep blacks, neon blue/purple gradients, glassmorphism cards, and sophisticated scroll-triggered animations (GSAP) to create an immersive, cinematic web experience.",
  "style": {
    "description": "The style essence is 'Futuristic Precision.' It pairs a technical sans-serif (Space Grotesk) with a bold, wide display font (Syncopate). The color palette is strictly dark (#050505) with vibrant neon highlights. Visual depth is achieved through an SVG noise overlay, a 40px geometric grid, and blurred radial blobs in the background. Components use glassmorphism with backdrop filters and thin, 1px borders.",
    "prompt": "Create a design with a deep black background (#050505). Overlay a subtle SVG noise texture (baseFrequency: 0.65, 5% opacity) and a geometric grid (40px spacing, #ffffff08). Typography: Use 'Syncopate' (Bold, Tracking: -0.05em) for hero headlines and 'Space Grotesk' (Weights: 300, 400, 600) for body and UI elements. Colors: Cyan (#00f2ff), Neon Purple (#bc13fe), and Emerald (#39ff14). Use glassmorphism for containers (Background: rgba(255, 255, 255, 0.03), backdrop-filter: blur(10px), border: 1px solid rgba(255, 255, 255, 0.08)). Animation style: Smooth scroll-triggered reveals using cubic-bezier(0.23, 1, 0.32, 1) and parallax image scaling (scale 1.12 to 1.0)."
  },
  "layout_and_structure": {
    "description": "A vertically structured layout with high-impact full-width sections. It begins with a cinematic hero, followed by a modular grid for services, a split-screen about section, and ends with a massive, typographic CTA.",
