      {
        "part": "Service Grid",
        "prompt": "A three-column grid of glass-effect cards. Each card has a large icon, bold Syncopate titles, and a hover effect that includes a slight Y-axis translation (-5px) and a border color change to the respective accent color."
      },
      {
        "part": "Content Split Section",
        "prompt": "A 50/50 split layout. Left: A square image with a grayscale filter (50% opacity) and a technical 'CORE_XX' label in the corner. Right: Modern editorial text with large stats (4xl font size) and a high-contrast 'Meet' button."
      },
      {
        "part": "Testimonials",
        "prompt": "A two-column grid featuring high-contrast testimonial cards. Each card has a 2px left-border in a neon accent color (Cyan or Purple) and uses italicized 'Space Grotesk' for quotes, creating a professional yet futuristic testimonial style."
      },
      {
        "part": "Typographic CTA & Footer",
